contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to invoke withdrawAll, withdraw and sendMoney from this contract (which is NOT the owner of c),
    // and observe whether address(c).balance decreases and whether the calls revert.
    // The rule: when this non-owner calls these functions, either the call reverts OR c's balance does not decrease.

    function run(uint sendValue, address target, uint sendAmt) public payable {
        require(address(this).balance >= sendValue, "insufficient balance for funding");
        // First fund c by triggering fallback via sending Ether to c
        // c.f{value: sendValue}("") is not available; use low-level call to hit fallback
        (bool okFund, ) = address(c).call{value: sendValue}("");
        // funding may succeed or fail; read balance before attempts
        uint before = address(c).balance;

        // Try withdrawAll
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }
        uint after1 = address(c).balance;

        // Try withdraw a specific amount
        bool withdrewReverted;
        try c.withdraw(sendAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint after2 = address(c).balance;

        // Try sendMoney to an arbitrary target (may trigger fallback or do nothing)
        // Ensure we have enough gas/conditions: no extra funding here.
        bool sendMoneyReverted;
        try c.sendMoney(target, sendAmt) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }
        uint after3 = address(c).balance;

        // The contract c was deployed with owner = deployer of C, which is not this test contract.
        // Therefore any successful attempt to transfer funds out of c by this contract would indicate a violation.
        // Assert: For each of the three attempted operations, if it did NOT revert then c.balance did NOT decrease as a result.
        assert(
            (withdrewAllReverted || after1 >= before) &&
            (withdrewReverted || after2 >= after1) &&
            (sendMoneyReverted || after3 >= after2)
        );
    }

    // allow receiving Ether when address(this).call{value:...} triggers transfers
    receive() external payable {}
}

