        require(ok, "fallback call failed");

        // observe after fallback
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // As owner, call withdrawAll to drain the contract
        c.withdrawAll();

        uint finalBalance = address(c).balance;

        // General rule assertion:
        // After the owner (this contract) sends sendValue to C, depositsCount increases by exactly 1
        // and C's balance increases by sendValue; then withdrawAll called by owner makes C's balance zero.
        assert(afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + sendValue && finalBalance == 0);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // param: amount that owner will ask C to send back to this contract
    function run(uint sendBack) public payable {
        require(address(this).balance >= sendBack, "insufficient balance");

        // record before values
        uint beforeDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // As owner, instruct C to send Ether back to this contract
        c.sendMoney(address(this), sendBack);

        // record after values
        uint afterDeposits = c.depositsCount();
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // General rule: depositsCount unchanged, C's balance decreased by sendBack (or to zero if insufficient),
        // and this contract's balance increased by the same amount C lost.
        // Express decrease equivalently: beforeCBalance - afterCBalance == afterThisBalance - beforeThisBalance
        // and depositsCount unchanged.
        assert(afterDeposits == beforeDeposits && beforeCBalance - afterCBalance == afterThisBalance - beforeThisBalance);
    }

    receive() external payable { }
}

