contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Receive to accept any refunds/transfers
    receive() external payable {}

    // params: callType: 0 = withdrawAll(), 1 = withdraw(amount)
    // amount: value to withdraw when callType==1; also used to send Ether into c for setup
    function run(uint8 callType, uint amount) public payable {
        require(callType <= 1);
        // fund this test contract sufficiently if it will send Ether to c
        // If we plan to send Ether to c for setup, ensure balance available
        if (address(this).balance < amount) {
            // try to make the require false in setups where amount is too large; leave to caller
            revert("insufficient balance to fund test");
        }

        // Record owner and depositsCount before any actions
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balanceBefore = address(c).balance;

        // Optionally fund c by calling its fallback (send Ether to contract address)
        // Send exactly `amount` to c to create a scenario where withdraw may succeed
        if (amount > 0) {
            // send ETH to c so its balance increases and fallback increments depositsCount
            (bool sent,) = address(c).call{value: amount}("");
            // ignore sent flag; the fallback increments depositsCount when payable fallback is executed
        }

        // Read fresh state after potential funding
        uint depositsAfterFund = c.depositsCount();
        uint balanceAfterFund = address(c).balance;

        bool reverted;
        // Make the decision call under test as top-level statement
        if (callType == 0) {
            // withdrawAll may revert if not owner; in this test the InvMutTest contract is the deployer of c
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe after-state
        address ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint balanceAfter = address(c).balance;

        // Assert general rule:
        // - owner must remain unchanged
        // - depositsCount must never decrease (fallback only increments), and withdraw calls do not change depositsCount
        // - if the withdraw call succeeded (did not revert) then the contract's balance after is <= balanceAfterFund
        //   and the decrease is at most the requested amount (for withdraw) or at most balanceAfterFund (for withdrawAll)
        if (!reverted) {
            if (callType == 0) {
                // withdrawAll should not increase balance; final balance is <= before
                assert(ownerAfter == ownerBefore && depositsAfter == depositsAfterFund && balanceAfter <= balanceAfterFund);
            } else {
                // withdraw(amount): final balance is >= balanceAfterFund - amount
                // equivalently, amount >= balanceAfterFund - balanceAfter
                assert(ownerAfter == ownerBefore && depositsAfter == depositsAfterFund && amount >= (balanceAfterFund - balanceAfter));
            }
        } else {
            // If reverted, still owner unchanged and depositsCount didn't decrease
            assert(ownerAfter == ownerBefore && depositsAfter >= depositsBefore);
        }
    }
}

